    <button class="proposal-fab" id="proposal-open" type="button" aria-label="Sampaikan usulan" aria-expanded="false" aria-controls="proposal-chat"><span class="fab-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M20 11.5a7.5 7.5 0 0 1-7.5 7.5H5l1.7-3.4A7.5 7.5 0 1 1 20 11.5Z"/><path d="M8 11h8M8 14h5"/></svg></span><span class="fab-label">Sampaikan usulan</span></button>
    <section class="chat-panel" id="proposal-chat" aria-label="Form usulan warga" aria-hidden="true"><div class="chat-head"><strong>Usulan warga</strong><button id="proposal-close" type="button" aria-label="Tutup percakapan"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="chat-body"><div id="chat-messages" aria-live="polite"></div><div id="chat-controls"></div><div class="chat-actions" id="chat-actions"></div><div class="chat-error" id="chat-error" role="alert"></div></div></section>
    <dialog class="dialog" id="service-dialog"><div class="dialog-head"><strong id="service-dialog-title"></strong><button id="service-close" class="overlay-close" type="button" aria-label="Tutup">×</button></div><div class="dialog-body"><p>Persyaratan dan alur layanan belum tersedia.</p></div></dialog>
    <script>
        const safeNode=(tag,className,value)=>{const node=document.createElement(tag);node.className=className;node.textContent=value??'';return node};
        const money=value=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value||0);
        if('IntersectionObserver'in window&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>entry.target.classList.toggle('is-visible',entry.isIntersecting)),{threshold:.12});document.querySelectorAll('main > section').forEach(section=>{section.classList.add('reveal');observer.observe(section)})}
        const nav=document.querySelector('#main-nav'),menuButton=document.querySelector('#menu-toggle');menuButton.addEventListener('click',()=>{const open=nav.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Tutup menu':'Buka menu')});nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false')}));
        const serviceDialog=document.querySelector('#service-dialog');document.querySelectorAll('.service-open').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#service-dialog-title').textContent=button.dataset.service;serviceDialog.showModal()}));document.querySelector('#service-close').addEventListener('click',()=>serviceDialog.close());serviceDialog.addEventListener('click',event=>{if(event.target===serviceDialog)serviceDialog.close()});
        const projectFields=[['Lokasi',p=>p.location],['Tahun',p=>p.year],['Status',p=>p.status],['Volume',p=>p.volume],['Sumber dana',p=>p.funding],['Pelaksana',p=>p.executor],['Jadwal',p=>p.schedule],['Progres',p=>`${p.progress??0}%`],['Realisasi',p=>money(p.spent)]];
        function renderProjects(projects,emptyMessage='Belum ada informasi pembangunan yang dapat ditampilkan.'){const list=document.querySelector('#project-list');list.replaceChildren();list.setAttribute('aria-busy','false');if(!projects.length){list.append(safeNode('p','portal-data-empty',emptyMessage));return}projects.forEach(project=>{const card=document.createElement('article');card.className='project-card';const meta=document.createElement('div');meta.className='project-meta';meta.append(safeNode('span','','Tahun '+(project.year||'—')),safeNode('span','project-status',project.status||'Status'));const main=document.createElement('div');main.append(safeNode('h3','',project.title),safeNode('p','',project.summary||project.location||'Ringkasan pekerjaan belum tersedia.'));const bottom=document.createElement('div');bottom.className='project-bottom';bottom.append(safeNode('small','',project.funding||'Anggaran belum tersedia'));const detail=safeNode('button','project-detail','Rincian pekerjaan');detail.type='button';bottom.append(detail);card.append(meta,main,bottom);const overlay=document.createElement('div');overlay.className='project-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-label','Rincian '+project.title);const head=document.createElement('div');head.className='overlay-head';head.append(safeNode('strong','','Rincian pekerjaan'));const close=safeNode('button','overlay-close','×');close.type='button';close.setAttribute('aria-label','Tutup rincian');close.addEventListener('click',()=>overlay.classList.remove('open'));head.append(close);overlay.append(head);projectFields.forEach(([label,get])=>{const value=get(project);if(value===undefined||value===null||value==='')return;const row=document.createElement('div');row.className='overlay-row';row.append(safeNode('span','',label),safeNode('strong','',value));overlay.append(row)});detail.addEventListener('click',()=>overlay.classList.add('open'));card.append(overlay);list.append(card)})}

        fetch('/api/desa/randupitu/content').then(r=>r.ok?r.json():Promise.reject()).then(data=>renderProjects(Array.isArray(data.projects)?data.projects:[])).catch(()=>renderProjects([],'Informasi pembangunan belum dapat dimuat saat ini.'));
        const year=document.querySelector('#budget-year'),lines=document.querySelector('#budget-lines'),realized=document.querySelector('#budget-realized');let budgets=[];function renderBudget(value){const budget=budgets.find(item=>String(item.year)===String(value));if(!budget)return;document.querySelector('#budget-sample')?.remove();lines.replaceChildren();[['Dana Desa',budget.villageFund],['Alokasi Dana Desa',budget.villageAllocation],['Bagi Hasil Pajak',budget.taxRevenueShare],['Bagi Hasil Retribusi',budget.retributionShare]].forEach(([label,amount])=>{const row=document.createElement('div');row.className='budget-line';row.append(safeNode('span','',label),safeNode('strong','',amount>0?money(amount):'Belum tersedia'));lines.append(row)});realized.textContent='Belum tersedia';}year.addEventListener('change',()=>renderBudget(year.value));fetch('/api/desa/randupitu/budgets').then(r=>r.ok?r.json():Promise.reject()).then(data=>{budgets=data;if(!budgets.length)return;year.hidden=false;budgets.forEach(item=>{const option=document.createElement('option');option.value=item.year;option.textContent=String(item.year);year.append(option)});year.value=String(budgets[0].year);renderBudget(year.value)}).catch(()=>{});
        const questions=[{key:'title',label:'Judul usulan',prompt:'Apa usulan yang ingin disampaikan?',required:true,type:'text'},{key:'location',label:'Lokasi',prompt:'Di mana usulan ini diperlukan?',required:true,type:'text'},{key:'category',label:'Bidang',prompt:'Pilih bidang usulan.',required:false,type:'choice',options:['Infrastruktur','Lingkungan','Sosial','Ekonomi','Lainnya']},{key:'description',label:'Uraian',prompt:'Jelaskan usulan secara singkat.',required:true,type:'textarea'},{key:'name',label:'Nama',prompt:'Nama (opsional).',required:false,type:'text'},{key:'contact',label:'Kontak',prompt:'Nomor telepon (opsional).',required:false,type:'text'}];let answers={},step=0;const chat=document.querySelector('#proposal-chat'),messages=document.querySelector('#chat-messages'),controls=document.querySelector('#chat-controls'),actions=document.querySelector('#chat-actions'),error=document.querySelector('#chat-error'),proposalButton=document.querySelector('#proposal-open');function say(text){messages.append(safeNode('div','chat-message',text));messages.scrollTop=messages.scrollHeight}function action(label,handler,primary=false){const button=safeNode('button',primary?'primary':'',label);button.type='button';button.addEventListener('click',handler);return button}function closeChat(clear=true){chat.classList.remove('open');chat.setAttribute('aria-hidden','true');proposalButton.setAttribute('aria-expanded','false');if(clear){answers={};step=0;messages.replaceChildren();controls.replaceChildren();actions.replaceChildren();error.textContent=''}}function renderQuestion(){controls.replaceChildren();actions.replaceChildren();error.textContent='';if(step>=questions.length){say('Periksa kembali usulanmu sebelum dikirim.');say(`${answers.title}\n${answers.location}\n${answers.description}`);actions.append(action('Batal',()=>closeChat()),action('Kirim usulan',submitProposal,true));return}const question=questions[step];say(question.prompt);controls.append(safeNode('div','chat-prompt',`${step+1} dari ${questions.length} · ${question.label}`));if(question.type==='choice'){const options=document.createElement('div');options.className='chat-options';question.options.forEach(option=>options.append(action(option,()=>{answers[question.key]=option;say(option);step++;renderQuestion()})));controls.append(options)}else{const input=document.createElement(question.type==='textarea'?'textarea':'input');input.className='chat-input';input.placeholder=question.label;input.setAttribute('aria-label',question.label);input.maxLength=question.key==='description'?3000:160;if(question.type==='textarea')input.rows=3;controls.append(input)}actions.append(action('Batal',()=>closeChat()));if(!question.required)actions.append(action('Lewati',()=>{answers[question.key]='';step++;renderQuestion()}));const next=action(step===questions.length-1?'Tinjau':'Lanjut',()=>{const input=controls.querySelector('input,textarea'),value=input?.value.trim()||'';if(question.required&&!value){error.textContent='Bagian ini perlu diisi.';return}answers[question.key]=value;if(value)say(value);step++;renderQuestion()},true);if(question.type==='choice')next.hidden=true;actions.append(next)}async function submitProposal(){error.textContent='';const button=actions.querySelector('.primary');button.disabled=true;try{const response=await fetch('/api/desa/randupitu/proposals',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||''},body:JSON.stringify({...answers,website:''})});const result=response.status===204?{}:await response.json();if(!response.ok)throw new Error(result.message||'Usulan belum berhasil dikirim.');messages.replaceChildren();controls.replaceChildren();actions.replaceChildren();say(result.message||'Usulan berhasil dikirim.');actions.append(action('Selesai',()=>closeChat(),true))}catch(exception){error.textContent=exception.message;button.disabled=false}}proposalButton.addEventListener('click',()=>{chat.classList.add('open');chat.setAttribute('aria-hidden','false');proposalButton.setAttribute('aria-expanded','true');if(!messages.childElementCount)renderQuestion()});document.querySelector('#proposal-close').addEventListener('click',()=>closeChat(false));
    </script>
    @include('desa.partials.managed-content')
    @include('desa.partials.responsive')
